 void symbol(Model m,float x,float y,float r,int color){if(m==null){center("○",x,y+5,20,color);return;}String g=m.group();if(g.equals("Amp")||g.equals("Preamp")){box(x-r*.65f,y-r*.85f,r*1.3f,r*1.7f,Color.TRANSPARENT,color,3);circle(x,y+5,r*.35f,0,color,2);circle(x,y-8,2,color,0,0);}else if(g.equals("Delay")){circle(x-5,y,r*.7f,0,color,2);circle(x+5,y,r*.7f,0,color,2);}else if(g.equals("Reverb")){Path path=new Path();path.moveTo(x,y-r);path.lineTo(x+r,y-r/2);path.lineTo(x+r,y+r/2);path.lineTo(x,y+r);path.lineTo(x-r,y+r/2);path.lineTo(x-r,y-r/2);path.close();p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);canvas.drawPath(path,p);line(x-r,y-r/2,x,y, color,1);line(x+r,y-r/2,x,y,color,1);line(x,y,x,y+r,color,1);p.setStyle(Paint.Style.FILL);}else if(g.equals("Cab / IR")){circle(x,y,r,0,color,2);circle(x,y,r*.65f,0,color,1);}else if(g.equals("Dynamics")||g.equals("EQ")){line(x-r,y+r,x+r,y-r,color,2);if(g.equals("Dynamics")){line(x-4,y+4,x+r,y-2,color,1);line(x-4,y+4,x+r,y-8,color,1);}}else if(g.equals("Pitch / Synth")){for(int i=0;i<4;i++)rect(x-r+i*r/2,y-r,r/3,r*2,color);}else if(!m.io.isEmpty()){center(m.io.equals("outputs")?"→":"↟",x,y+9,27,color);}else{Path wave=new Path();for(int i=0;i<=32;i++){float xx=x-r+i*r/16,yy=y+(float)Math.sin(i*.65)*r*.65f;if(i==0)wave.moveTo(xx,yy);else wave.lineTo(xx,yy);}p.setStyle(Paint.Style.STROKE);p.setColor(color);p.setStrokeWidth(2);canvas.drawPath(wave,p);p.setStyle(Paint.Style.FILL);}}
